package com.wandertrace.service;
import com.wandertrace.dto.AuthDtos.*; import com.wandertrace.exception.*; import com.wandertrace.security.CurrentUser; import jakarta.servlet.http.HttpSession; import java.util.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AuthService { private final JdbcTemplate db; private final PasswordEncoder passwords; public AuthService(JdbcTemplate db,PasswordEncoder passwords){this.db=db;this.passwords=passwords;} @Transactional public User register(Registration request,HttpSession session){if(!db.queryForList("select id from users where lower(email)=lower(?)",request.email()).isEmpty())throw new DuplicateResourceException("Email is already registered");UUID id=UUID.randomUUID();db.update("insert into users(id,email,password_hash,display_name,role) values(?,?,?,?,?)",id,request.email().trim().toLowerCase(),passwords.encode(request.password()),request.displayName().trim(),"USER");session.changeSessionId();session.setAttribute(CurrentUser.SESSION_KEY,id);return new User(id,request.email().trim().toLowerCase(),request.displayName().trim(),"USER");} public User login(Credentials request,HttpSession session){var rows=db.queryForList("select id,email,password_hash,display_name,role from users where lower(email)=lower(?)",request.email());if(rows.isEmpty()||!passwords.matches(request.password(),(String)rows.getFirst().get("password_hash")))throw new AccessDeniedException();var row=rows.getFirst();UUID id=(UUID)row.get("id");session.changeSessionId();session.setAttribute(CurrentUser.SESSION_KEY,id);return map(row);} public User me(UUID id){var rows=db.queryForList("select id,email,display_name,role from users where id=?",id);if(rows.isEmpty())throw new AccessDeniedException();return map(rows.getFirst());} public void logout(HttpSession session){session.invalidate();} private User map(Map<String,Object> row){return new User((UUID)row.get("id"),(String)row.get("email"),(String)row.get("display_name"),(String)row.get("role"));}}
